using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;using EternalSteam.OpenWorld;using EternalSteam.Demo;
public static class MeasureGameHotPaths {
 static JObject Measure(Action action,int count){for(int i=0;i<8;i++)action();var times=new double[count];long bytes=GC.GetAllocatedBytesForCurrentThread();var sw=new System.Diagnostics.Stopwatch();for(int i=0;i<count;i++){sw.Restart();action();sw.Stop();times[i]=sw.Elapsed.TotalMilliseconds;}bytes=GC.GetAllocatedBytesForCurrentThread()-bytes;Array.Sort(times);return new JObject{{"calls",count},{"medianMs",times[count/2]},{"p95Ms",times[(int)(count*.95)]},{"maxMs",times.Last()},{"bytesPerCall",bytes/(double)count}};}
 public static string Main(string label){if(!Application.isPlaying)throw new Exception("Play required");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var s=h.Sandbox;h.Groups.Select(false);h.Groups.Advance(1);s.Persistence.Automatic=false;var j=new JObject{{"label",label},{"hudRefresh",Measure(h.Refresh,240)},{"dockApply",Measure(()=>h.Layout.CompactDock.Apply(1),240)},{"simulationEmpty",Measure(()=>s.AdvanceSimulation(1f/60),240)}};foreach(var count in new[]{0,1000,10000}){var w=new HordeEnemyWorld(null,false,100000,new Rect(-500,-500,1000,1000)){ArrivalPolicy=EnemyArrivalPolicy.Remain};for(int i=0;i<count;i++)w.TrySpawn(new Vector3(i%100,0,i/100),new Vector3(i%100,0,i/100),0);j["move"+count]=Measure(()=>w.MoveAndIndex(1f/60),240);}
 var grid=s.WorldGrid;var late=(Action)Delegate.CreateDelegate(typeof(Action),grid,typeof(WorldGridView).GetMethod("LateUpdate",BindingFlags.Instance|BindingFlags.NonPublic));grid.SetVisible(true);var timer=System.Diagnostics.Stopwatch.StartNew();late();timer.Stop();j["gridFirstMs"]=timer.Elapsed.TotalMilliseconds;j["gridRebuilds"]=grid.RebuildCount;grid.SetVisible(false);File.WriteAllText("Docs/Measurements/2026-10-03-performance/"+label+"-hotpaths.json",j.ToString());return j.ToString();}
 public static string Focus(){var w=EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView"));w.Focus();w.maximized=true;return "GameView focused and maximized for matched before/after sampling";}
}
